import { useState, useEffect } from 'react';

import Grid from '@mui/material/Grid';
import { styled, useTheme } from '@mui/material/styles';
import {
  Box,
  Card,
  Chip,
  Stack,
  Select,
  MenuItem,
  Typography,
  InputLabel,
  FormControl,
  SelectChangeEvent,
} from '@mui/material';

import { fCurrency } from 'src/utils/format-number';
import { formatBoule, transformedBoule } from 'src/utils/lottery-games';

import { useTranslate } from 'src/locales';
import { useSelector, useDispatch } from 'src/redux/store';
import { getTickets } from 'src/redux/slices/ticket';

import Iconify from 'src/components/iconify';
import { getWallet } from 'src/redux/slices/wallet';
import { height, padding } from '@mui/system';

const TicketCardContainer = styled(Card)(({ theme }) => ({
  padding: 16,
  background: 'white',
  borderRadius: 13,
  flexDirection: 'column',
  justifyContent: 'flex-start',
  gap: 4,
  display: 'flex',
  marginBottom: theme.spacing(3),
}));

const StatusChip = styled(Chip)(({ theme }) => ({
  fontWeight: theme.typography.fontWeightBold,
  padding: theme.spacing(0.5, 2),
}));

const getStatusChipStyle = (status: string, theme: any) => {
  switch (status) {
    case 'WIN':
      return { backgroundColor: theme.palette.success.main, color: theme.palette.common.white };
    case 'WRONG':
      return { backgroundColor: theme.palette.error.main, color: theme.palette.common.white };
    case 'PENDING':
      return { backgroundColor: theme.palette.warning.main, color: theme.palette.common.white };
    default:
      return { backgroundColor: theme.palette.grey[400], color: theme.palette.common.white };
  }
};

const getBallChipStyle = (value: string) => {
  const digits = String(value || '').replace(/\D/g, '');
  const n = digits ? parseInt(digits.slice(-2), 10) : 0;
  const hue = Number.isNaN(n) ? 210 : (n * 37) % 360;

  return {
    borderRadius: .6,
    padding: '0px 4px',
    height: 20,
    color: '#fff',
    fontWeight: 800,
    boxShadow: '0 1px 2px rgba(0,0,0,.25)',
    backgroundImage: `linear-gradient(135deg, hsl(${hue},70%,45%), hsl(${(hue + 40) % 360},70%,35%))`,
    '& .MuiChip-label': {
      px: 0,
      width: '100%',
      textAlign: 'center',
      fontSize: 12,
      fontWeight: 700,
      whiteSpace: 'normal',
    },
  };
};

export default function TicketCasino() {
  const dispatch = useDispatch();
  const { t } = useTranslate();
  const { tickets } = useSelector((state) => state.ticket);
  const [statusFilter, setStatusFilter] = useState('ALL');

  useEffect(() => {
    dispatch(getTickets());
    dispatch(getWallet());
  }, [dispatch]);

  const handleStatusChange = (event: SelectChangeEvent<string>) => {
    setStatusFilter(event.target.value as string);
  };

  const filteredTickets =
    statusFilter === 'ALL'
      ? tickets
      : tickets.filter((ticket: any) => ticket.status === statusFilter);

  return (
    <Grid container spacing={3}>
      <Grid item xs={12} md={8}>
        <FormControl variant="outlined" fullWidth>
          <InputLabel>{t('layout.status_filter')}</InputLabel>
          <Select
            value={statusFilter}
            onChange={handleStatusChange}
            label={t('layout.status_filter')}
          >
            <MenuItem value="ALL">{t('status_filter.ALL')}</MenuItem>
            <MenuItem value="WIN">{t('status_filter.WIN')}</MenuItem>
            <MenuItem value="WRONG">{t('status_filter.WRONG')}</MenuItem>
            <MenuItem value="PENDING">{t('status_filter.PENDING')}</MenuItem>
          </Select>
        </FormControl>
      </Grid>
      <Grid item xs={12} md={8}>
        {filteredTickets.map((ticket: any) => (
          <Stack key={ticket.id}>
            <TicketCard ticket={ticket} />
          </Stack>
        ))}
      </Grid>
    </Grid>
  );
}

function TicketCard({ ticket }: any) {
  const theme = useTheme();
  const { t } = useTranslate();
  const { wallet } = useSelector((state) => state.wallet);
  const ticketTirage = ticket?.tirage;
  const ticketBoules = Array.isArray(ticket?.boules?.boules) ? ticket.boules.boules : [];
  const getLottoLabel = (lotto: string) => {
    if (lotto === 'L3') return t('loto.label_l3') || 'Loto3';
    if (lotto === 'L4') return t('loto.label_l4') || 'Loto4';
    if (lotto === 'L5') return t('loto.label_l5') || 'Loto5';
    if (lotto === 'MA') return t('loto.label_ma') || 'Mariage';
    if (lotto === 'BO') return t('loto.label_bo') || 'Borlette';
    if (lotto === 'P2') return t('loto.label_p2') || 'Pick2';
    if (lotto === 'P5') return t('loto.label_p5') || 'Pick5';
    if (lotto === 'L3B') return t('loto.label_l3b') || 'Loto3 Box';
    if (lotto === 'L4B') return t('loto.label_l4b') || 'Loto4 Box';
    return lotto;
  };

  return (
    <TicketCardContainer>
      <Box display="flex" justifyContent="space-between">
        <Box display="flex" alignItems="center">
          <Iconify icon="fluent-emoji-flat:ticket" width={30} height={30} sx={{ marginRight: 2 }} />
          <Box>
            <Typography variant="h6" component="div">
              {t(`game.${ticket.game_name}`)}
            </Typography>
            <Typography variant="subtitle1" color="textSecondary">
              {ticket.ref_code}
            </Typography>
          </Box>
        </Box>
        <Box display="flex" alignItems="center">
          <StatusChip
            label={t(`status_filter.${ticket.status}`)}
            style={getStatusChipStyle(ticket.status, theme)}
            sx={{ mr: 2 }}
          />
        </Box>
      </Box>
      <Typography variant="body2" color="textSecondary" gutterBottom>
        {new Date(ticket.created_on).toLocaleString()}
      </Typography>
      {ticketTirage && (
        <Typography variant="body2" color="textSecondary">
          {`${t('draw_title') || 'Tirage'}: ${ticketTirage}`}
        </Typography>
      )}
      {ticketBoules.length > 0 && (
        <Stack spacing={0.5} sx={{ mt: 0.5 }}>
          <Typography variant="body2" fontWeight={500}>
            Boules:
          </Typography>
          {ticketBoules.map((item: any, index: number) => {
            const lotto = String(item?.lotto || '');
            const option = String(item?.option || '');
            const rawBoule = String(item?.boule || '');
            const displayPlay =
              formatBoule(transformedBoule(rawBoule, lotto), lotto, option) || rawBoule;

            return (
              <Stack
                key={`${ticket.id}-boule-${index}`}
                direction="row"
                spacing={1.25}
                alignItems="center"
              >
                <Chip label={displayPlay} sx={getBallChipStyle(displayPlay)} />
                <Typography variant="body2" color="textSecondary">
                  {`${getLottoLabel(lotto)} • ${t('betslip.mise') || 'Mise'}: ${
                    item?.montant ?? 0
                  } ${
                    wallet?.currency || ''
                  }${
                    item?.montantWin !== undefined && item?.montantWin !== null
                      ? ` • ${t('betslip.gain') || 'Gain'}: ${item.montantWin} ${
                          wallet?.currency || ''
                        }`
                      : ''
                  }`}
                </Typography>
              </Stack>
            );
          })}
        </Stack>
      )}
      <Box mt={2}>
        <Box display="flex" justifyContent="space-between" alignItems="center">
          <Typography variant="body2">
            {t('betslip.mise_total')}: {fCurrency(ticket.mise, false)} {wallet?.currency}
          </Typography>
          <Typography variant="body2">
            {t('betslip.gain_potentiel')}: {fCurrency(ticket.gain, false)} {wallet?.currency}
          </Typography>
        </Box>
      </Box>
    </TicketCardContainer>
  );
}
