import { useState, useEffect, useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';

import Tab from '@mui/material/Tab';
import Tabs from '@mui/material/Tabs';
import Container from '@mui/material/Container';

import { useTranslate } from 'src/locales';

import Iconify from 'src/components/iconify';
import { useSettingsContext } from 'src/components/settings';

import AccountTicket from '../account-ticket';
import AccountGeneral from '../account-general';
import AccountTransaction from '../account-transaction';
import AccountTicketCasino from '../account-ticket-casino';
import AccountChangePassword from '../account-change-password';
import AccountReferral from '../account-referral';

export default function AccountView() {
  const { t } = useTranslate();
  const TABS = [
    {
      value: 'ticket',
      label: t('layout.my_bets'),
      icon: <Iconify icon="twemoji:admission-tickets" width={24} />,
    },
    // {
    //   value: 'ticket_casino',
    //   label: t('layout.my_bets_casino'),
    //   icon: <Iconify icon="cil:casino" width={24} />,
    // },
    {
      value: 'transaction',
      label: t('wallet.my_transactions'),
      icon: <Iconify icon="grommet-icons:transaction" width={24} />,
    },
    {
      value: 'referral',
      label: t('layout.referral') || 'Referral',
      icon: <Iconify icon="mdi:gift-outline" width={24} />,
    },
    {
      value: 'general',
      label: t('layout.my_infos'),
      icon: <Iconify icon="solar:user-id-bold" width={24} />,
    },
    {
      value: 'security',
      label: t('layout.change_password'),
      icon: <Iconify icon="ic:round-vpn-key" width={24} />,
    },
  ];
  const settings = useSettingsContext();
  const location = useLocation();
  const navigate = useNavigate();
  const menu = new URLSearchParams(location.search).get('menu');

  const [currentTab, setCurrentTab] = useState(menu || 'transaction');

  useEffect(() => {
    navigate(`?menu=${menu}`, { replace: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [menu]);

  const handleChangeTab = useCallback(
    (event: React.SyntheticEvent, newValue: string) => {
      setCurrentTab(newValue);
      navigate(`?menu=${newValue}`);
    },
    [navigate]
  );

  return (
    <Container maxWidth={settings.themeStretch ? false : 'lg'}>
      <Tabs
        value={currentTab}
        onChange={handleChangeTab}
        sx={{
          mb: { xs: 3, md: 5 },
        }}
      >
        {TABS.map((tab) => (
          <Tab key={tab.value} label={tab.label} icon={tab.icon} value={tab.value} />
        ))}
      </Tabs>

      {currentTab === 'general' && <AccountGeneral />}
      {/* {currentTab === 'ticket' && <AccountTicket />} */}
      {currentTab === 'ticket' && <AccountTicketCasino />}
      {currentTab === 'transaction' && <AccountTransaction />}
      {currentTab === 'security' && <AccountChangePassword />}
      {currentTab === 'referral' && <AccountReferral />}
    </Container>
  );
}
