import React, { useState } from 'react';

import Card from '@mui/material/Card';
import Stack from '@mui/material/Stack';
import Button from '@mui/material/Button';
import Divider from '@mui/material/Divider';
import MenuItem from '@mui/material/MenuItem';
import CardHeader from '@mui/material/CardHeader';
import Typography from '@mui/material/Typography';
import InputLabel from '@mui/material/InputLabel';
import FormControl from '@mui/material/FormControl';
import ListItemText from '@mui/material/ListItemText';
import Select, { SelectChangeEvent } from '@mui/material/Select';

import { useBoolean } from 'src/hooks/use-boolean';

import { fDate } from 'src/utils/format-time';
import { fCurrency } from 'src/utils/format-number';

import { useTranslate } from 'src/locales';

import Iconify from 'src/components/iconify';

// ----------------------------------------------------------------------

type Props = {
  transactions: any[];
  wallet: any;
};

const transactionTypes = [
  'ALL',
  'DEPOSIT',
  'WITHDRAW',
  'TRANSFER',
  'PLAY',
  'MISTAKE',
  'PAYWINNER',
  'REFUND',
  'INTEREST',
];

export default function AccountBillingHistory({ transactions, wallet }: Props) {
  const showMore = useBoolean();
  const { t } = useTranslate();
  const [filter, setFilter] = useState('ALL');

  const handleFilterChange = (event: SelectChangeEvent<string>) => {
    const newFilter = event.target.value;
    setFilter(newFilter);
  };
  const filteredTransactions = transactions.filter(
    (transaction) => filter === 'ALL' || transaction.type_transaction === filter
  );

  return (
    <Card>
      <CardHeader title={t('wallet.my_transactions')} />

      <Stack spacing={1.5} sx={{ px: 3, pt: 3 }}>
        <FormControl sx={{ mb: 3, minWidth: 120 }}>
          <InputLabel id="transaction-filter-label">{t('layout.filter_by')}</InputLabel>
          <Select
            labelId="transaction-filter-label"
            id="transaction-filter"
            value={filter}
            onChange={handleFilterChange}
            label={t('layout.filter_by')}
          >
            {transactionTypes.map((type) => (
              <MenuItem key={type} value={type}>
                {t(`transaction_filter.${type}`)}
              </MenuItem>
            ))}
          </Select>
        </FormControl>

        {(showMore.value ? filteredTransactions : filteredTransactions.slice(0, 8)).map(
          (transaction) => (
            <Stack key={transaction.id} direction="row" alignItems="center">
              <ListItemText
                primary={transaction.ref_code}
                secondary={fDate(transaction.created_on)}
                primaryTypographyProps={{
                  typography: 'body2',
                }}
                secondaryTypographyProps={{
                  mt: 0.5,
                  component: 'span',
                  typography: 'caption',
                  color: 'text.disabled',
                }}
              />

              <Typography variant="body2" sx={{ textAlign: 'right', mr: 5 }}>
                {fCurrency(transaction.amount, false)} {wallet?.currency}
              </Typography>

              <Typography variant="body2" sx={{ textAlign: 'right', mr: 5 }}>
                {t(`transaction_filter.${transaction.type_transaction}`)}
              </Typography>
            </Stack>
          )
        )}

        <Divider sx={{ borderStyle: 'dashed' }} />
      </Stack>

      <Stack alignItems="flex-start" sx={{ p: 2 }}>
        <Button
          size="small"
          color="inherit"
          startIcon={
            <Iconify
              icon={showMore.value ? 'eva:arrow-ios-upward-fill' : 'eva:arrow-ios-downward-fill'}
            />
          }
          onClick={showMore.onToggle}
        >
          {showMore.value ? `Show Less` : `Show More`}
        </Button>
      </Stack>
    </Card>
  );
}
